-- ============================================================
--  007 — school years: the School Year list on Submit Research
--
--  Adds two small tables:
--    school_years  school years an admin added or hid (label like '2026–2027').
--                  The current school year and the 4 before it are generated by
--                  the app and need no rows; a row for a generated year only
--                  records that an admin hid it (is_active = 0).
--    app_settings  key/value settings. Today: school_year_start_month
--                  (1-12, default 6 = June) — the month a school year begins.
--
--  research_submissions.school_year / .program are NOT changed: they stay
--  VARCHAR columns, and older free-text values are kept exactly as they are.
--
--  Already applied automatically at boot by ensureSchoolYearsSchema()
--  (server/lib/school-years.js). This file is the same change as SQL for a
--  manual run.
--
--  APPLY
--    mysql -h <host> -P <port> -u <user> -p <database> < db/migrations/007_school_years.sql
--
--  ROLLBACK
--    DROP TABLE school_years;
--    DROP TABLE app_settings;   -- only if nothing else uses it
--  The form then offers only the generated years (current + previous 4).
-- ============================================================

CREATE TABLE IF NOT EXISTS school_years (
  id          INT NOT NULL AUTO_INCREMENT,
  label       VARCHAR(20) NOT NULL,
  is_active   TINYINT(1) NOT NULL DEFAULT 1,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_school_years_label (label)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS app_settings (
  setting_key    VARCHAR(60) NOT NULL,
  setting_value  VARCHAR(255) NOT NULL DEFAULT '',
  updated_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (setting_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
